-- =============================================================================
--  CREATE BANK USERS  (from CAS Security Matrix -> SysUser_CAS, 28/07/2026)
--  Bulk-creates the bank staff as LDAP users with roles, committee membership and
--  team membership. ADDITIVE + idempotent (insert-only, guarded by NOT EXISTS);
--  safe to re-run. Does NOT touch menus or existing roles' permissions.
--
--  PREREQUISITE: run CreateBankRoles.sql first (creates Inquiry / Report / IT Security).
--  LDAP users: PasswordHash = NULL, AuthSource = 'LDAP', MustChangePassword = 0
--  (matches how the app's RegistrationService creates LDAP accounts). Email is left
--  NULL when the sheet has none (LDAP syncs it at first login).
--
--  Mappings applied:
--    'Inquiry + Report' column  -> both Inquiry and Report roles
--    'High Privilege'  column   -> Admin role
--    'AppraisalCommittee'       -> AspNetRole AppraisalCommittee + committee member of
--                                  COMMITTEE and COMMITTEE_WITH_MEETING
--    'AppraisalSubCommittee'    -> committee member of SUB_COMMITTEE (NO AspNetRole)
--    Team column                -> auth.TeamMembers (generic 'ประเมินราคาหลักประกัน'
--                                  and blank are ignored)
-- =============================================================================

SET QUOTED_IDENTIFIER ON;
SET NOCOUNT ON;
SET XACT_ABORT ON;

BEGIN TRANSACTION;

DECLARE @UserId UNIQUEIDENTIFIER;
DECLARE @CID_SUB  UNIQUEIDENTIFIER = (SELECT Id FROM workflow.Committees WHERE Code = 'SUB_COMMITTEE');
DECLARE @CID_COM  UNIQUEIDENTIFIER = (SELECT Id FROM workflow.Committees WHERE Code = 'COMMITTEE');
DECLARE @CID_COMM UNIQUEIDENTIFIER = (SELECT Id FROM workflow.Committees WHERE Code = 'COMMITTEE_WITH_MEETING');

-- Ensure the 5 bank teams exist (insert-only by Name).
DECLARE @Teams TABLE (Name NVARCHAR(200));
INSERT INTO @Teams (Name) VALUES (N'ประเมินราคาหลักประกัน 1'),(N'ประเมินราคาหลักประกัน 2'),(N'ประเมินราคาหลักประกัน 3'),(N'ประเมินราคาหลักประกัน 4'),(N'สนับสนุนประเมินราคาหลักประกัน');
INSERT INTO auth.Teams (Id, Name, Scope)
SELECT NEWID(), t.Name, N'Bank' FROM @Teams t
WHERE NOT EXISTS (SELECT 1 FROM auth.Teams x WHERE x.Name = t.Name);

-- P5461  เยียรยง ผลบุญ
IF NOT EXISTS (SELECT 1 FROM auth.AspNetUsers WHERE NormalizedUserName = N'P5461')
  INSERT INTO auth.AspNetUsers (Id, UserName, NormalizedUserName, Email, NormalizedEmail, EmailConfirmed, PasswordHash, SecurityStamp, ConcurrencyStamp, PhoneNumberConfirmed, TwoFactorEnabled, LockoutEnabled, AccessFailedCount, FirstName, LastName, Position, Department, EmployeeId, AuthSource, IsActive, MustChangePassword, CompanyId)
  VALUES (NEWID(), N'P5461', N'P5461', N'Yearayongp@lhbank.co.th', UPPER(N'Yearayongp@lhbank.co.th'), 0, NULL, UPPER(CAST(NEWID() AS NVARCHAR(36))), CAST(NEWID() AS NVARCHAR(36)), 0, 0, 1, 0, N'เยียรยง', N'ผลบุญ', NULL, N'บริหารความปลอดภัยและบคส.ระบบ IT', N'05461', N'LDAP', 1, 0, NULL);
SET @UserId = (SELECT Id FROM auth.AspNetUsers WHERE NormalizedUserName = N'P5461');
INSERT INTO auth.AspNetUserRoles (UserId, RoleId) SELECT @UserId, r.Id FROM auth.AspNetRoles r WHERE r.NormalizedName IN (N'IT SECURITY') AND NOT EXISTS (SELECT 1 FROM auth.AspNetUserRoles ur WHERE ur.UserId=@UserId AND ur.RoleId=r.Id);

